target = ".....((((((((...((((((((((..((((..........))))..((((..........))))..((((..........))))..))))))))))...((((((((((..((((..........))))..((((..........))))..((((..........))))..))))))))))...((((((((((..((((..........))))..((((..........))))..((((..........))))..))))))))))...))))))))....."
n=len(target)
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
opens=[i for i in range(n) if target[i]=='(' and i<pairs[i]]
stems5=[]
cur=[]
for o in opens:
    if cur and o==cur[-1]+1: cur.append(o)
    else:
        if cur: stems5.append(cur)
        cur=[o]
if cur: stems5.append(cur)
comp={'G':'C','C':'G','A':'U','U':'A'}
def rc(s): return ''.join(comp[c] for c in reversed(s))
def build(codes, unpaired='A'):
    seq=[unpaired]*n
    for k,s in enumerate(stems5):
        code=codes[k]
        for idx,pos in enumerate(s):
            seq[pos]=code[idx]
            seq[pairs[pos]]=rc(code)[idx]
    return ''.join(seq)
gc4=[''.join(p) for p in itertools.product('GC',repeat=4)]
gc8=[''.join(p) for p in itertools.product('GC',repeat=8)]
gc10=[''.join(p) for p in itertools.product('GC',repeat=10)]
rng=random.Random(31337)
cands=[]
for _ in range(400):
    c0=rng.choice(gc8)
    bigs=rng.sample(gc10,3)
    smalls=rng.sample(gc4,9)
    codes=[c0,bigs[0],smalls[0],smalls[1],smalls[2],bigs[1],smalls[3],smalls[4],smalls[5],bigs[2],smalls[6],smalls[7],smalls[8]]
    cands.append(build(codes))
print(json.dumps(cands))
import sys; print(len(cands), file=sys.stderr)
